-- Migration: 000005_update_categories_40.up.sql
-- Description: Standardizes and expands the platform categories to the 40 official MVP categories pointing to high-quality contextual internet photography for testing environments.

-- 1. Upsert the 40 official categories first
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    icon_url = EXCLUDED.icon_url,
    description = EXCLUDED.description,
    is_active = EXCLUDED.is_active;

-- 2. Reassign any services using legacy category IDs
UPDATE services 
SET category_id = 'c0000000-0000-0000-0000-000000000005' 
WHERE id = '22222222-0000-0000-0000-000000000012'; -- Ar Condicionado

UPDATE services 
SET category_id = '00000000-0000-0000-0000-000000000099' 
WHERE category_id IN ('d72ab993-0000-0000-0000-000000000005', '3cc18f77-0000-0000-0000-000000000010');

-- 3. Remove old unmapped categories
DELETE FROM categories 
WHERE id IN ('d72ab993-0000-0000-0000-000000000005', '3cc18f77-0000-0000-0000-000000000010');
